insert into public.nastavitve (id, podatki) values (1, '{"podjetje":{"ime":"Napihljiva Igrala Kids Joy","kratkoIme":"Kids Joy","slogan":"Oddajamo v najem napihljiva igrala za vse priložnosti in krasimo prostore z baloni.","telefon":"070 258 245","email":"kidsjoy.igrala@gmail.com","instagram":"kids_joy_a2","facebook":"https://www.facebook.com/share/1J8Crnadih/","naslov":"Kromberk, Solkan, 5000 Nova Gorica","obmocje":"Goriška in okolica","delovniCas":"Vedno odprto, pokličite kadarkoli","dostava":"Gratis v Novi Gorici, drugje po dogovoru","cenaOd":60,"cenaDo":100},"hero":{"naslov":"Skakanje, smeh in nepozabne zabave","podnaslov":"Pripeljemo, postavimo in pospravimo, vi pa uživate."},"obvestilo":"","prednosti":[{"ikona":"🛡️","naslov":"Varni in kakovostni","opis":"Redno čiščenje in dezinfekcija igral."},{"ikona":"🎉","naslov":"Za vse priložnosti","opis":"Rojstni dnevi, praznovanja, zabave in šole."},{"ikona":"🏠","naslov":"Notri in zunaj","opis":"Primerni za dvorane, vrtce in vrtove."},{"ikona":"⚡","naslov":"Hitra postavitev","opis":"Pripeljemo, postavimo in pospravimo mi."}],"kraji":["Kanal","Renče","Bilje","Nova Gorica","Solkan","Dijaški dom"],"vprasanja":[{"vprasanje":"Koliko stane najem?","odgovor":"Cena na dan je od 60 € do 100 €, odvisno od igrala. Za dekoracije pripravimo ponudbo glede na velikost in želje."},{"vprasanje":"Ali je dostava vključena?","odgovor":"Na območju Nove Gorice je dostava brezplačna. Za ostala območja se dogovorimo."},{"vprasanje":"Za koliko stare otroke so igrala?","odgovor":"Igrala so namenjena otrokom od 3 do 9 let. Skupna nosilnost je do 250 kg."},{"vprasanje":"Kaj potrebujem na lokaciji?","odgovor":"Raven prostor, nekaj metrov prostora okoli igrala in električno vtičnico za ventilator. Igrala lahko postavimo notri ali zunaj."},{"vprasanje":"Kaj če dežuje?","odgovor":"Ob dežju ali močnem vetru igrala ne postavljamo zunaj. Prestavimo ga v notranji prostor ali dogovorimo nov termin."},{"vprasanje":"Kdo postavi igralo?","odgovor":"Igralo pripeljemo, postavimo, razložimo varno uporabo in ga po koncu tudi pospravimo."}]}'::jsonb)
insert into public.ponudba (slug, kategorija, ime, kratek_opis, opis, cena, mere, starost, nosilnost, znacilnosti, slike, barve, oblika, aktivno, vrstni_red) values
  ('mavricni-grad', 'igralo', 'Mavrični grad s toboganom', 'Klasični grad za skakanje z manjšim toboganom. Idealen za dvorane.', 'Barvit grad, ki ga otroci obožujejo. Ima prostor za skakanje in tobogan, zato je odličen za rojstne dneve doma ali v dvorani. Zaradi kompaktne velikosti ga postavimo tudi v manjše prostore.', 60, 'pribl. 4 × 3,5 m, višina 2,5 m', '3 do 9 let', 'do 250 kg', array['Primeren za notranjo uporabo', 'Hitra postavitev', 'Mreža za varnost ob straneh']::text[], array[]::text[], array['#e8412c', '#2f6fdb', '#f6c026']::text[], 'grad', true, 1),
  ('grad-z-zogicami', 'igralo', 'Grad s toboganom in bazenom žogic', 'Skakanje, tobogan in bazen z barvnimi žogicami v enem.', 'Igralo z dvema doživetjema: najprej skakanje in plezanje, nato spust po toboganu naravnost v bazen z barvnimi žogicami. Žogice so vključene v najem.', 80, 'pribl. 5 × 4 m, višina 2,8 m', '3 do 9 let', 'do 250 kg', array['Bazen z žogicami vključen', 'Notranja in zunanja uporaba', 'Mreža za varnost ob straneh']::text[], array[]::text[], array['#3db34a', '#f6c026', '#e8412c']::text[], 'zogice', true, 2),
  ('veliki-tobogan', 'igralo', 'Veliki grad z dvojnim toboganom', 'Naše največje igralo, 6 m dolžine in 3 m višine. Zvezda vsake zabave.', 'Velik grad z visokim plezalnim delom in dvojnim toboganom. Najbolj priljubljen za večja praznovanja, šolske dneve in prireditve na prostem, kjer se zabava več otrok hkrati.', 100, '6 × 4 m, višina 3 m', '3 do 9 let', 'do 250 kg', array['Največje igralo v ponudbi', 'Odlično za prireditve na prostem', 'Hkrati več otrok']::text[], array[]::text[], array['#f08a1c', '#7b4fc9', '#2f6fdb']::text[], 'tobogan', true, 3),
  ('rojstni-dan', 'dekoracija', 'Rojstnodnevna dekoracija', 'Baloni, številke in ozadje za fotografiranje v izbranih barvah.', 'Postavimo balonski lok ali steno, velike številke za leta in usklajene barve po želji. Lahko jo kombinirate z najemom igrala.', null, '', '', '', array['Barve po želji', 'Velike številke', 'Ozadje za fotografije']::text[], array[]::text[], array['#e8412c', '#f6c026', '#2f6fdb']::text[], 'baloni', true, 1),
  ('balonski-lok', 'dekoracija', 'Balonski lok in girlande', 'Organski lok ali girlanda za vhod, mizo s sladicami ali oder.', 'Balonske girlande in loki različnih dolžin za vhod, sladko mizo ali oder. Primerno za vrtce, šole, otvoritve in zabave.', null, '', '', '', array['Različne dolžine', 'Notri in zunaj', 'Postavitev in odvoz']::text[], array[]::text[], array['#7b4fc9', '#f39ac0', '#ffffff']::text[], 'baloni', true, 2),
  ('krst-obhajilo', 'dekoracija', 'Krst, obhajilo in birma', 'Nežne pastelne dekoracije za družinska praznovanja.', 'Pastelne barve, bele in zlate podrobnosti ter napis z imenom. Dekoracijo uskladimo s prostorom in mizo.', null, '', '', '', array['Pastelni toni', 'Napis z imenom', 'Usklajeno s prostorom']::text[], array[]::text[], array['#9fd3f5', '#f7d9e3', '#e9c46a']::text[], 'baloni', true, 3),
  ('poroka-obletnica', 'dekoracija', 'Poroke in obletnice', 'Elegantna dekoracija dvorane z baloni v vaših barvah.', 'Dekoracija dvorane, vhoda in glavne mize. Uporabljamo elegantne kombinacije barv in kovinske balone.', null, '', '', '', array['Elegantne kombinacije', 'Dekoracija dvorane', 'Postavitev in odvoz']::text[], array[]::text[], array['#ffffff', '#e9c46a', '#c9a227']::text[], 'baloni', true, 4)
